INSERT INTO `pages` (`id`, `slug`, `title`, `meta_description`, `meta_keywords`, `content`, `extra_heading`, `extra_subheading`, `extra_hero_image`, `cta_text`, `cta_link`, `contact_heading`, `contact_subheading`, `contact_map_embed`, `story_title`, `why_choose_subtitle`, `stats_counters`, `custom_data`, `status`, `meta_title`, `is_published`, `order`, `created_at`, `updated_at`, `hero_image_id`, `story_image_id`) VALUES
(1, 'about-us', 'About Us – Afro-Vertex Tours & Safaris', 'Welcome to Afro-Vertex Africa Tanzania Safari LTD, where the Africa adventures meet the untamed beauty of nature!', 'Afro vertex tours, Reach us, kilimanjaro climbing', '<p>Welcome to Afro-Vertex Africa Tanzania Safari LTD, where the Africa adventures meet the untamed beauty of nature!&nbsp;Afro-Vertex Africa Tanzania Safari LTD is&nbsp;a premier travel, tour, safari operator / company / Destination Management Company (DMC), agency&nbsp;headquartered in Tanzania, Africa dedicated to crafting immersive and unforgettable wildlife experiences and adventures across the Africa world most stunning safari and tour destinations.</p>', 'Welcome to the Best Tour Operator in Tanzania - Afro Vertex Tours', 'Afro-Vertex Tours & Safaris, headquartered in Moshi, Tanzania, is a highly rated tour operator specializing in Mount Kilimanjaro treks, Serengeti safaris, and Zanzibar beach holidays. Reviews consistently praise their professional guides, well-organized itineraries, and excellent client care, making them a top-choice for adventure travelers.', NULL, 'Play You Trip With Us', 'http://localhost/avt/pages/contact', NULL, NULL, NULL, 'Roam Through Our Africa Tours & Safari Tales', 'At Afro-Vertex Tours & Safaris, we believe Africa Tours & safari is more than just a trip—it’s a life-changing journey. It’s about feeling the thrill of spotting a lion in its natural habitat, watching a herd of elephants march through the golden savanna,', '[{\"value\":\"50\",\"suffix\":\"+\",\"label\":\"Destinations\"},{\"value\":\"2000\",\"suffix\":\"+\",\"label\":\"Guided Tours\"},{\"value\":\"2000\",\"suffix\":\"+\",\"label\":\"Happy Travellers\"},{\"value\":\"10\",\"suffix\":\"+\",\"label\":\"Years of Experience\"}]', '[{\"name\":\"Frank Michael\",\"role\":\"Founder & CEO\",\"bio\":\"To connect travelers with nature in the most immersive, ethical, and breathtaking way possible. We strive to provide extraordinary safari experiences that are not only thrilling but also support conservation efforts, respect local cultures, and promote eco-friendly tourism.\",\"photo_image_id\":\"604\"},{\"name\":\"Michael Tossi\",\"role\":\"Lead Guide\",\"bio\":\"dedicated to crafting immersive and unforgettable wildlife experiences and adventures across the Africa world most stunning safari and tour destinations.\",\"photo_image_id\":\"652\"},{\"name\":\"Deogratias Isaya\",\"role\":\"Cook\",\"bio\":\"Afro-Vertex Tours & Safaris brings you closer to nature in the most exciting and responsible way possible.\",\"photo_image_id\":\"623\"},{\"name\":\"Sarah Mkubwa\",\"role\":\"Sales & Marketing\",\"bio\":\"At Afro-Vertex Tours & Safaris, we believe Africa Tours & safari is more than just a trip\\u2014it\\u2019s a life-changing journey.\",\"photo_image_id\":\"629\"}]', 'published', 'About Us – Afro-Vertex Tours & Safaris', 1, 999, '2026-07-01 10:04:40', '2026-07-02 03:34:29', 632, 640),
(3, 'contact', 'Contact Us', NULL, NULL, '<p>Let us guide you on your next tour in Africa, where the standard &amp; luxury meets the allure of Africa, and every detail is curated to perfection.</p>', NULL, NULL, NULL, NULL, NULL, 'Reach Out to Our Dedicated Africa Travel Experts', 'Let us guide you on your next tour in Africa, where the standard & luxury meets the allure of Africa, and every detail is curated to perfection.', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d8121254.186155508!2d29.695238055198818!3d-6.334908285368404!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x1839d915db3be101%3A0xfd37b27378368e8!2sAfro-Vertex%20Tours%20%26%20Safaris!5e0!3m2!1sen!2stz!4v1782911418751!5m2!1sen!2stz\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\"></iframe>', NULL, NULL, '[]', '[]', 'published', NULL, 1, 999, '2026-07-01 10:08:26', '2026-07-01 10:11:05', 640, NULL),
(4, 'terms-and-conditions', 'Terms and Conditions', 'Welcome to Afro Vertex Tours By accessing or using our website and services, you agree to comply with and be bound by the following terms and conditions. Please read these carefully.', NULL, '<p>Welcome to Afro Vertex Tours By accessing or using our website and services, you agree to comply with and be bound by the following terms and conditions. Please read these carefully.</p>\r\n<h2 class=\"mb-2\">1. Acceptance of Terms</h2>\r\n<p>By using our services, you confirm that you are at least 18 years old and have the legal capacity to enter into agreements.</p>\r\n<h2 class=\"mb-2\">2. Services Offered</h2>\r\n<p>Travel Wecditr provides a platform for booking travel-related services, including flights, hotels, car rentals, and travel insurance. All bookings are subject to availability.</p>\r\n<h2 class=\"mb-2\">3. Pricing and Payments</h2>\r\n<div class=\"mb-4\">\r\n<p class=\"mb-1\">&nbsp;Prices displayed on our website are subject to change and may not include taxes and fees.</p>\r\n<p class=\"mb-1\">&nbsp;Payment must be made in full at the time of booking. We accept various payment methods as specified on our site.</p>\r\n<p>&nbsp;You are responsible for ensuring that your payment information is accurate.</p>\r\n</div>\r\n<h2 class=\"mb-2\">4. Booking Modifications and Cancellations</h2>\r\n<div class=\"mb-4\">\r\n<p class=\"mb-1\">&nbsp;Any modifications to bookings must be requested through customer support and are subject to applicable fees.</p>\r\n<p>&nbsp;Cancellations are governed by the cancellation policies of the respective service providers (airlines, hotels, etc.). Please review their policies carefully before booking.</p>\r\n</div>\r\n<h2 class=\"mb-2\">5.User Responsibilities</h2>\r\n<div>\r\n<p class=\"mb-1\">&nbsp;You agree to provide accurate and complete information during the booking process.</p>\r\n<p>&nbsp;You are responsible for ensuring that you have the necessary travel documents (e.g., passports, visas) and comply with all relevant regulations.</p>\r\n</div>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', '[]', 'published', 'Terms and Conditions of Afro Vertex Tours', 1, 994, '2026-07-02 03:20:15', '2026-07-02 03:20:15', NULL, NULL);
