INSERT INTO `testimonials` (`id`, `name`, `location`, `rating`, `content`, `tour_package_id`, `destination_id`, `avatar_image_id`, `is_featured`, `order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Gervas Venom', 'France', 4, 'The experience of trekking through Mount Kilimanjaro was truly incredible. The guides, porters, and the entire crew from Afro-Vertex Tours & Safaris, a top-rated Kilimanjaro hiking company in Moshi, went above and beyond to make the journey unforgettable.', NULL, NULL, NULL, 1, 1, 'published', '2026-07-01 08:11:59', '2026-07-01 08:11:59'),
(2, 'Yohana M', 'Uganda', 5, 'I met with Afro-Vertex Tours & Safaris members at which I booked Machame route 6 days Kilimanjaro climbing. It was awesome tour in which enjoyed a lot since it was care company with its excellent trained guide I learnt a lots through him, it was so best tour in Moshi. This is a best tour company in Tanzania for mg recommendation.', NULL, NULL, 636, 1, 2, 'published', '2026-07-01 08:52:36', '2026-07-01 08:52:36'),
(3, 'Nyamiche Yonick', 'Uzbekstan', 5, 'I can’t praise Afro-Vertex Tours & Safaris enough for the exceptional personal care they provided to our family of 12 during our recent safari Tanzania. Over the course of our 5-Day Safari tour, which included 4 National Parks and 4 different accommodations, we felt confident that our needs would be met and our questions answered. Our guides were professional, knowledgeable, caring, and genuinely enjoyable to be with. We truly appreciated our time spent with them.', NULL, NULL, 652, 1, 3, 'published', '2026-07-01 08:54:00', '2026-07-01 08:54:00');
